"""Food tracking in VitaLocal: own food catalog, dishes from components, native diary entries
(nutrition_entry extended) and manual body measurements.

Revision ID: 0021
Revises: 0020
Create Date: 2026-10-03
"""

from alembic import op

revision = "0021"
down_revision = "0020"
branch_labels = None
depends_on = None


def upgrade() -> None:
    op.execute("""
        -- Nutrients are per base_amount of base_unit (100 g, 100 ml, or n portions of a dish).
        -- The id is generated by the client so that a food created offline can be referenced
        -- by entries queued after it.
        CREATE TABLE food (
            id          uuid PRIMARY KEY,
            name        text NOT NULL CHECK (name <> ''),
            brand       text,
            barcode     text,
            base_amount double precision NOT NULL DEFAULT 100 CHECK (base_amount > 0),
            base_unit   text NOT NULL DEFAULT 'g' CHECK (base_unit IN ('g', 'ml', 'portion')),
            portions    jsonb NOT NULL DEFAULT '[]',
            nutrients   jsonb NOT NULL DEFAULT '{}',
            source      text NOT NULL DEFAULT 'vitalocal' CHECK (source IN ('vitalocal', 'off', 'waistline')),
            source_ref  text,
            source_data jsonb,
            favorite    boolean NOT NULL DEFAULT false,
            archived    boolean NOT NULL DEFAULT false,
            created_at  timestamptz NOT NULL DEFAULT now(),
            updated_at  timestamptz NOT NULL DEFAULT now()
        );
        CREATE INDEX food_barcode_idx ON food (barcode) WHERE barcode IS NOT NULL;
        CREATE INDEX food_updated_idx ON food (updated_at);
        -- one catalog food per Open Food Facts product / Waistline item
        CREATE UNIQUE INDEX food_source_ref_idx ON food (source, source_ref) WHERE source_ref IS NOT NULL;

        -- Dishes and recipes: amount in the component's base unit; the dish's nutrients are
        -- computed from its components when it is saved.
        CREATE TABLE food_component (
            food_id      uuid NOT NULL REFERENCES food ON DELETE CASCADE,
            position     int NOT NULL,
            component_id uuid NOT NULL REFERENCES food,
            amount       double precision NOT NULL CHECK (amount > 0),
            PRIMARY KEY (food_id, position)
        );
        CREATE INDEX food_component_component_idx ON food_component (component_id);

        -- Native entries live next to the Waistline ones, so every reader keeps working.
        ALTER TABLE nutrition_entry
            ADD COLUMN uid uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,
            ADD COLUMN food_id uuid REFERENCES food ON DELETE SET NULL,
            ADD COLUMN entered_via text,
            ADD COLUMN created_at timestamptz NOT NULL DEFAULT now(),
            ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(),
            ALTER COLUMN parse_run_id DROP NOT NULL,
            ADD CONSTRAINT nutrition_entry_waistline_run CHECK (source <> 'waistline' OR parse_run_id IS NOT NULL);
        CREATE INDEX nutrition_entry_day_only_idx ON nutrition_entry (day);
        CREATE INDEX nutrition_entry_food_idx ON nutrition_entry (food_id) WHERE food_id IS NOT NULL;

        -- Manual body measurements (weight came only from Waistline until now).
        CREATE TABLE body_entry (
            id         uuid PRIMARY KEY,
            ts         timestamptz NOT NULL,
            metric     text NOT NULL CHECK (metric IN ('weight', 'body_fat', 'body.waist', 'body.hips', 'body.neck')),
            value      double precision NOT NULL CHECK (value > 0),
            source     text NOT NULL DEFAULT 'webui',
            created_at timestamptz NOT NULL DEFAULT now()
        );
        CREATE INDEX body_entry_metric_ts_idx ON body_entry (metric, ts);
    """)


def downgrade() -> None:
    op.execute("""
        DROP TABLE body_entry;
        DELETE FROM nutrition_entry WHERE parse_run_id IS NULL;
        ALTER TABLE nutrition_entry
            DROP CONSTRAINT nutrition_entry_waistline_run,
            ALTER COLUMN parse_run_id SET NOT NULL,
            DROP COLUMN updated_at, DROP COLUMN created_at, DROP COLUMN entered_via,
            DROP COLUMN food_id, DROP COLUMN uid;
        DROP INDEX IF EXISTS nutrition_entry_day_only_idx;
        DROP TABLE food_component; DROP TABLE food;
    """)
